INSERT INTO USER_ROLES (
       USER_ID
     , ROLE_ID
     , FIRST_REGISTER_BRANCH
     , FIRST_REGISTER_USER
     , FIRST_REGISTER_DATE
     , FIRST_REGISTER_TIME
     , LAST_CHANGE_BRANCH
     , LAST_CHANGE_USER
     , LAST_CHANGE_DATE
     , LAST_CHANGE_TIME
) VALUES (
       #{userID}
     , #{roleId}
     , #{firstRegisterBranch}
     , #{firstRegisterUser}
     , #{firstRegisterDate}
     , #{firstRegisterTime}
     , #{lastChangeBranch}
     , #{lastChangeUser}
     , #{lastChangeDate}
     , #{lastChangeTime}
)

